import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FiTruck, FiShield, FiRefreshCw, FiHeadphones, FiArrowRight } from 'react-icons/fi';
import Header from '../components/Header';
import Footer from '../components/Footer';
import HeroCarousel from '../components/HeroCarousel';
import CategorySection from '../components/CategorySection';
import BrandSection from '../components/BrandSection';
import ProductCard from '../components/ProductCard';
import { products } from '../services/api';

const Home = () => {
  const [trendingProducts, setTrendingProducts] = useState([]);
  const [newArrivals, setNewArrivals] = useState([]);
  const [bestSellers, setBestSellers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [trendingRes, newArrivalsRes, bestSellersRes] = await Promise.allSettled([
          products.getAll({ sort: 'popularity', limit: 10 }),
          products.getAll({ sort: 'newest', limit: 10 }),
          products.getAll({ sort: 'rating', limit: 10 }),
        ]);

        if (trendingRes.status === 'fulfilled') setTrendingProducts(trendingRes.value.data.data || []);
        if (newArrivalsRes.status === 'fulfilled') setNewArrivals(newArrivalsRes.value.data.data || []);
        if (bestSellersRes.status === 'fulfilled') setBestSellers(bestSellersRes.value.data.data || []);
      } catch (err) {
        console.error('Failed to load products:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const offers = [
    { title: 'Flat 50% Off', subtitle: 'On premium sunglasses', color: '#2874f0', link: '/category/sunglasses' },
    { title: 'Buy 1 Get 1', subtitle: 'Selected eyeglasses', color: '#ff9f00', link: '/category/eyeglasses' },
    { title: 'Starting ₹299', subtitle: 'Contact lenses', color: '#26a541', link: '/category/contact-lenses' },
    { title: 'Extra ₹200 Off', subtitle: 'Use code: EYE200', color: '#ff6161', link: '/coupons' },
  ];

  const features = [
    { icon: <FiTruck size={24} />, title: 'Free Delivery', desc: 'On orders above ₹999' },
    { icon: <FiShield size={24} />, title: '100% Genuine', desc: 'Authentic products only' },
    { icon: <FiRefreshCw size={24} />, title: 'Easy Returns', desc: '7-day return policy' },
    { icon: <FiHeadphones size={24} />, title: '24/7 Support', desc: 'Dedicated help center' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <main style={{ flex: 1 }}>
        <HeroCarousel />

        <div className="container" style={{ marginTop: '16px' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '12px', marginBottom: '24px' }}>
            {offers.map((offer, idx) => (
              <Link key={idx} to={offer.link} style={{ background: offer.color, borderRadius: '8px', padding: '20px', color: '#fff', transition: 'transform 0.2s', textDecoration: 'none' }}>
                <div style={{ fontSize: '18px', fontWeight: 700, marginBottom: '4px' }}>{offer.title}</div>
                <div style={{ fontSize: '13px', opacity: 0.9 }}>{offer.subtitle}</div>
              </Link>
            ))}
          </div>

          <section style={{ marginBottom: '32px' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
              <h2 style={{ fontSize: '22px', fontWeight: 700, color: 'var(--text-primary)' }}>Trending Now</h2>
              <Link to="/search?sort=popularity" style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--primary)', fontSize: '14px', fontWeight: 500 }}>
                View All <FiArrowRight />
              </Link>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '16px' }}>
              {loading
                ? Array.from({ length: 5 }).map((_, i) => (
                    <div key={i} className="card" style={{ height: '280px' }}>
                      <div className="skeleton" style={{ height: '200px', width: '100%' }} />
                      <div style={{ padding: '12px' }}>
                        <div className="skeleton" style={{ height: '14px', width: '80%', marginBottom: '8px' }} />
                        <div className="skeleton" style={{ height: '14px', width: '50%' }} />
                      </div>
                    </div>
                  ))
                : trendingProducts.map((product) => (
                    <ProductCard key={product._id} product={product} />
                  ))}
            </div>
          </section>

          <CategorySection />

          <section style={{ marginBottom: '32px' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
              <h2 style={{ fontSize: '22px', fontWeight: 700, color: 'var(--text-primary)' }}>New Arrivals</h2>
              <Link to="/search?sort=newest" style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--primary)', fontSize: '14px', fontWeight: 500 }}>
                View All <FiArrowRight />
              </Link>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '16px' }}>
              {loading
                ? Array.from({ length: 5 }).map((_, i) => (
                    <div key={i} className="card" style={{ height: '280px' }}>
                      <div className="skeleton" style={{ height: '200px', width: '100%' }} />
                      <div style={{ padding: '12px' }}>
                        <div className="skeleton" style={{ height: '14px', width: '80%', marginBottom: '8px' }} />
                        <div className="skeleton" style={{ height: '14px', width: '50%' }} />
                      </div>
                    </div>
                  ))
                : newArrivals.map((product) => (
                    <ProductCard key={product._id} product={product} />
                  ))}
            </div>
          </section>

          <BrandSection />

          <section style={{ marginBottom: '32px' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
              <h2 style={{ fontSize: '22px', fontWeight: 700, color: 'var(--text-primary)' }}>Best Sellers</h2>
              <Link to="/search?sort=rating" style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--primary)', fontSize: '14px', fontWeight: 500 }}>
                View All <FiArrowRight />
              </Link>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '16px' }}>
              {loading
                ? Array.from({ length: 5 }).map((_, i) => (
                    <div key={i} className="card" style={{ height: '280px' }}>
                      <div className="skeleton" style={{ height: '200px', width: '100%' }} />
                      <div style={{ padding: '12px' }}>
                        <div className="skeleton" style={{ height: '14px', width: '80%', marginBottom: '8px' }} />
                        <div className="skeleton" style={{ height: '14px', width: '50%' }} />
                      </div>
                    </div>
                  ))
                : bestSellers.map((product) => (
                    <ProductCard key={product._id} product={product} />
                  ))}
            </div>
          </section>

          <section style={{ background: 'var(--bg-white)', borderRadius: '8px', padding: '24px', marginBottom: '32px', boxShadow: 'var(--shadow)' }}>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '24px', textAlign: 'center' }}>
              {features.map((feature, idx) => (
                <div key={idx} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                  <div style={{ color: 'var(--primary)', background: 'var(--primary-light)', width: '48px', height: '48px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    {feature.icon}
                  </div>
                  <h4 style={{ fontSize: '14px', fontWeight: 600 }}>{feature.title}</h4>
                  <p style={{ fontSize: '12px', color: 'var(--text-light)' }}>{feature.desc}</p>
                </div>
              ))}
            </div>
          </section>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Home;
